      - id  = "foo" -> null
    }`,
		},
	}

	for name, tc := range testCases {
		t.Run(name, func(t *testing.T) {
			blockSchema := testSchema(configschema.NestingSingle)
			fullSchema := &terraform.Schemas{
				Providers: map[addrs.Provider]providers.ProviderSchema{
